<?php
namespace Modules\Glitter\NotificationHub\Http\Controllers\Admin;use App\Helpers\ResponseHelper;use App\Http\Controllers\Api\Base\AdminBaseController;use Illuminate\Http\JsonResponse;use Modules\Glitter\NotificationHub\DTO\Admin\NotificationAttemptSearchData;use Modules\Glitter\NotificationHub\Http\Requests\Admin\ListNotificationAttemptsRequest;use Modules\Glitter\NotificationHub\Http\Resources\Admin\NotificationAttemptCollection;use Modules\Glitter\NotificationHub\Http\Resources\Admin\NotificationAttemptResource;use Modules\Glitter\NotificationHub\Services\Admin\NotificationHubAdminService;
class NotificationAttemptController extends AdminBaseController { public function __construct(private readonly NotificationHubAdminService $service){} public function index(ListNotificationAttemptsRequest $r):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.attempts_retrieved',new NotificationAttemptCollection($this->service->listAttempts(NotificationAttemptSearchData::fromArray($r->validated()))));} public function show(string $attempt):JsonResponse{return ResponseHelper::moduleSuccess('glitter-notification_hub','messages.attempt_retrieved',new NotificationAttemptResource($this->service->getAttempt($attempt)));} }
